use std::fmt;

/// A byte-offset span in the source string (`start..end`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    #[inline]
    pub const fn new(start: usize, end: usize) -> Self {
        Self { start, end }
    }
}

/// The kind of a lexical token.
#[derive(Debug, Clone, PartialEq)]
pub enum TokenKind {
    Number(f64),
    Ident(String),
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Caret,
    LParen,
    RParen,
    Eof,
}

impl fmt::Display for TokenKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TokenKind::Number(n) => write!(f, "number `{}`", n),
            TokenKind::Ident(s) => write!(f, "identifier `{}`", s),
            TokenKind::Plus => write!(f, "`+`"),
            TokenKind::Minus => write!(f, "`-`"),
            TokenKind::Star => write!(f, "`*`"),
            TokenKind::Slash => write!(f, "`/`"),
            TokenKind::Percent => write!(f, "`%`"),
            TokenKind::Caret => write!(f, "`^`"),
            TokenKind::LParen => write!(f, "`(`"),
            TokenKind::RParen => write!(f, "`)`"),
            TokenKind::Eof => write!(f, "end of input"),
        }
    }
}

/// A token paired with its source span.
#[derive(Debug, Clone, PartialEq)]
pub struct Token {
    pub kind: TokenKind,
    pub span: Span,
}

impl Token {
    #[inline]
    pub const fn new(kind: TokenKind, span: Span) -> Self {
        Self { kind, span }
    }
}

/// Errors that can occur during lexing or parsing.
#[derive(Debug, Clone, PartialEq)]
pub enum ParseError {
    UnexpectedChar {
        ch: char,
        span: Span,
    },
    InvalidNumber {
        lexeme: String,
        span: Span,
    },
    UnexpectedToken {
        expected: &'static str,
        found: TokenKind,
        span: Span,
    },
    RecursionLimitExceeded {
        span: Span,
    },
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::UnexpectedChar { ch, span } => {
                write!(
                    f,
                    "unexpected character `{}` at {}..{}",
                    ch, span.start, span.end
                )
            }
            ParseError::InvalidNumber { lexeme, span } => {
                write!(
                    f,
                    "invalid number literal `{}` at {}..{}",
                    lexeme, span.start, span.end
                )
            }
            ParseError::UnexpectedToken {
                expected,
                found,
                span,
            } => {
                write!(
                    f,
                    "expected {}, found {} at {}..{}",
                    expected, found, span.start, span.end
                )
            }
            ParseError::RecursionLimitExceeded { span } => {
                write!(
                    f,
                    "maximum recursion depth exceeded at {}..{}",
                    span.start, span.end
                )
            }
        }
    }
}

impl std::error::Error for ParseError {}

/// Unary arithmetic operators.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum UnaryOp {
    Plus,
    Neg,
}

impl fmt::Display for UnaryOp {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UnaryOp::Plus => write!(f, "+"),
            UnaryOp::Neg => write!(f, "-"),
        }
    }
}

/// Binary arithmetic operators.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BinaryOp {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Pow,
}

impl fmt::Display for BinaryOp {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BinaryOp::Add => write!(f, "+"),
            BinaryOp::Sub => write!(f, "-"),
            BinaryOp::Mul => write!(f, "*"),
            BinaryOp::Div => write!(f, "/"),
            BinaryOp::Rem => write!(f, "%"),
            BinaryOp::Pow => write!(f, "^"),
        }
    }
}

/// An Abstract Syntax Tree node for an arithmetic expression.
#[derive(Debug, Clone, PartialEq)]
pub enum Expr {
    Number(f64),
    Variable(String),
    Unary {
        op: UnaryOp,
        expr: Box<Expr>,
    },
    Binary {
        op: BinaryOp,
        left: Box<Expr>,
        right: Box<Expr>,
    },
}

impl fmt::Display for Expr {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Expr::Number(n) => write!(f, "{}", n),
            Expr::Variable(name) => write!(f, "{}", name),
            Expr::Unary { op, expr } => write!(f, "({}{})", op, expr),
            Expr::Binary { op, left, right } => write!(f, "({} {} {})", left, op, right),
        }
    }
}

/// Tokenizer for arithmetic expressions with variables.
pub struct Lexer<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Lexer<'a> {
    pub const fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    /// Tokenizes the entire input into a vector of tokens terminated by `TokenKind::Eof`.
    pub fn tokenize(&mut self) -> Result<Vec<Token>, ParseError> {
        let mut tokens = Vec::new();
        loop {
            let token = self.next_token()?;
            let is_eof = token.kind == TokenKind::Eof;
            tokens.push(token);
            if is_eof {
                break;
            }
        }
        Ok(tokens)
    }

    /// Reads and returns the next token from the input.
    pub fn next_token(&mut self) -> Result<Token, ParseError> {
        self.skip_whitespace();

        let start = self.pos;
        let Some(ch) = self.peek_char() else {
            return Ok(Token::new(TokenKind::Eof, Span::new(start, start)));
        };

        let single = match ch {
            '+' => Some(TokenKind::Plus),
            '-' => Some(TokenKind::Minus),
            '*' => Some(TokenKind::Star),
            '/' => Some(TokenKind::Slash),
            '%' => Some(TokenKind::Percent),
            '^' => Some(TokenKind::Caret),
            '(' => Some(TokenKind::LParen),
            ')' => Some(TokenKind::RParen),
            _ => None,
        };

        if let Some(kind) = single {
            self.advance_char();
            return Ok(Token::new(kind, Span::new(start, self.pos)));
        }

        if ch.is_ascii_digit() || ch == '.' {
            return self.lex_number();
        }

        if ch.is_ascii_alphabetic() || ch == '_' {
            return Ok(self.lex_ident());
        }

        self.advance_char();
        Err(ParseError::UnexpectedChar {
            ch,
            span: Span::new(start, self.pos),
        })
    }

    fn lex_number(&mut self) -> Result<Token, ParseError> {
        let start = self.pos;
        let mut has_digits = false;

        while let Some(c) = self.peek_char() {
            if c.is_ascii_digit() {
                has_digits = true;
                self.advance_char();
            } else {
                break;
            }
        }

        if self.peek_char() == Some('.') {
            self.advance_char();
            while let Some(c) = self.peek_char() {
                if c.is_ascii_digit() {
                    has_digits = true;
                    self.advance_char();
                } else {
                    break;
                }
            }
        }

        if !has_digits {
            let lexeme = self.input[start..self.pos].to_string();
            return Err(ParseError::InvalidNumber {
                lexeme,
                span: Span::new(start, self.pos),
            });
        }

        if matches!(self.peek_char(), Some('e' | 'E')) {
            self.advance_char();
            if matches!(self.peek_char(), Some('+' | '-')) {
                self.advance_char();
            }
            while let Some(c) = self.peek_char() {
                if c.is_ascii_digit() {
                    self.advance_char();
                } else {
                    break;
                }
            }
        }

        let lexeme = &self.input[start..self.pos];
        let value = lexeme.parse::<f64>().map_err(|_| ParseError::InvalidNumber {
            lexeme: lexeme.to_string(),
            span: Span::new(start, self.pos),
        })?;

        Ok(Token::new(
            TokenKind::Number(value),
            Span::new(start, self.pos),
        ))
    }

    fn lex_ident(&mut self) -> Token {
        let start = self.pos;
        while let Some(c) = self.peek_char() {
            if c.is_ascii_alphanumeric() || c == '_' {
                self.advance_char();
            } else {
                break;
            }
        }
        let ident = self.input[start..self.pos].to_string();
        Token::new(TokenKind::Ident(ident), Span::new(start, self.pos))
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek_char() {
            if c.is_whitespace() {
                self.advance_char();
            } else {
                break;
            }
        }
    }

    #[inline]
    fn peek_char(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    #[inline]
    fn advance_char(&mut self) -> Option<char> {
        let ch = self.peek_char()?;
        self.pos += ch.len_utf8();
        Some(ch)
    }
}

/// Default maximum recursion depth for the parser.
pub const DEFAULT_MAX_DEPTH: usize = 256;

/// Recursive-descent parser for arithmetic expressions.
///
/// Grammar (from lowest to highest precedence):
/// ```text
/// expr    := term ( ('+' | '-') term )*
/// term    := unary ( ('*' | '/' | '%') unary )*
/// unary   := ('+' | '-') unary | power
/// power   := primary ( '^' unary )?
/// primary := NUMBER | IDENT | '(' expr ')'
/// ```
pub struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    depth: usize,
    max_depth: usize,
}

impl Parser {
    pub fn new(tokens: Vec<Token>) -> Self {
        Self::with_max_depth(tokens, DEFAULT_MAX_DEPTH)
    }

    pub fn with_max_depth(tokens: Vec<Token>, max_depth: usize) -> Self {
        Self {
            tokens,
            pos: 0,
            depth: 0,
            max_depth,
        }
    }

    /// Parses a complete expression and ensures all tokens are consumed.
    pub fn parse(&mut self) -> Result<Expr, ParseError> {
        let expr = self.parse_expr()?;
        let next = self.peek();
        if next.kind != TokenKind::Eof {
            return Err(ParseError::UnexpectedToken {
                expected: "end of input",
                found: next.kind.clone(),
                span: next.span,
            });
        }
        Ok(expr)
    }

    fn parse_expr(&mut self) -> Result<Expr, ParseError> {
        self.enter_recursion()?;
        let result = (|| {
            let mut left = self.parse_term()?;
            loop {
                let op = match self.peek().kind {
                    TokenKind::Plus => BinaryOp::Add,
                    TokenKind::Minus => BinaryOp::Sub,
                    _ => break,
                };
                self.advance();
                let right = self.parse_term()?;
                left = Expr::Binary {
                    op,
                    left: Box::new(left),
                    right: Box::new(right),
                };
            }
            Ok(left)
        })();
        self.exit_recursion();
        result
    }

    fn parse_term(&mut self) -> Result<Expr, ParseError> {
        let mut left = self.parse_unary()?;
        loop {
            let op = match self.peek().kind {
                TokenKind::Star => BinaryOp::Mul,
                TokenKind::Slash => BinaryOp::Div,
                TokenKind::Percent => BinaryOp::Rem,
                _ => break,
            };
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::Binary {
                op,
                left: Box::new(left),
                right: Box::new(right),
            };
        }
        Ok(left)
    }

    fn parse_unary(&mut self) -> Result<Expr, ParseError> {
        self.enter_recursion()?;
        let result = (|| {
            let op = match self.peek().kind {
                TokenKind::Plus => Some(UnaryOp::Plus),
                TokenKind::Minus => Some(UnaryOp::Neg),
                _ => None,
            };
            if let Some(op) = op {
                self.advance();
                let expr = self.parse_unary()?;
                Ok(Expr::Unary {
                    op,
                    expr: Box::new(expr),
                })
            } else {
                self.parse_power()
            }
        })();
        self.exit_recursion();
        result
    }

    fn parse_power(&mut self) -> Result<Expr, ParseError> {
        let base = self.parse_primary()?;
        if self.peek().kind == TokenKind::Caret {
            self.advance();
            let exponent = self.parse_unary()?;
            Ok(Expr::Binary {
                op: BinaryOp::Pow,
                left: Box::new(base),
                right: Box::new(exponent),
            })
        } else {
            Ok(base)
        }
    }

    fn parse_primary(&mut self) -> Result<Expr, ParseError> {
        let token = self.peek().clone();
        match token.kind {
            TokenKind::Number(n) => {
                self.advance();
                Ok(Expr::Number(n))
            }
            TokenKind::Ident(name) => {
                self.advance();
                Ok(Expr::Variable(name))
            }
            TokenKind::LParen => {
                self.advance();
                let expr = self.parse_expr()?;
                let closing = self.peek();
                if closing.kind == TokenKind::RParen {
                    self.advance();
                    Ok(expr)
                } else {
                    Err(ParseError::UnexpectedToken {
                        expected: "`)`",
                        found: closing.kind.clone(),
                        span: closing.span,
                    })
                }
            }
            _ => Err(ParseError::UnexpectedToken {
                expected: "number, variable, or `(`",
                found: token.kind,
                span: token.span,
            }),
        }
    }

    #[inline]
    fn peek(&self) -> &Token {
        self.tokens
            .get(self.pos)
            .unwrap_or_else(|| self.tokens.last().expect("token stream must end with Eof"))
    }

    #[inline]
    fn advance(&mut self) {
        if self.pos + 1 < self.tokens.len() {
            self.pos += 1;
        }
    }

    #[inline]
    fn enter_recursion(&mut self) -> Result<(), ParseError> {
        self.depth += 1;
        if self.depth > self.max_depth {
            self.depth -= 1;
            return Err(ParseError::RecursionLimitExceeded {
                span: self.peek().span,
            });
        }
        Ok(())
    }

    #[inline]
    fn exit_recursion(&mut self) {
        self.depth -= 1;
    }
}

/// Convenience function to tokenize and parse an arithmetic expression string.
pub fn parse(input: &str) -> Result<Expr, ParseError> {
    let tokens = Lexer::new(input).tokenize()?;
    Parser::new(tokens).parse()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_precedence_and_associativity() {
        let ast = parse("1 + 2 * 3 - 4 / 2").unwrap();
        assert_eq!(ast.to_string(), "((1 + (2 * 3)) - (4 / 2))");
    }

    #[test]
    fn parses_right_associative_power_and_unary() {
        assert_eq!(parse("2 ^ 3 ^ 4").unwrap().to_string(), "(2 ^ (3 ^ 4))");
        assert_eq!(parse("-2 ^ 2").unwrap().to_string(), "(-(2 ^ 2))");
        assert_eq!(parse("2 ^ -3").unwrap().to_string(), "(2 ^ (-3))");
        assert_eq!(parse("--x").unwrap().to_string(), "(-(-x))");
    }

    #[test]
    fn parses_variables_and_parentheses() {
        let ast = parse("(x_1 + y2) * _z % 5").unwrap();
        assert_eq!(ast.to_string(), "(((x_1 + y2) * _z) % 5)");
    }

    #[test]
    fn parses_float_and_scientific_notation() {
        let ast = parse(".5 + 1.25e-2 * 3E+4").unwrap();
        assert_eq!(ast.to_string(), "(0.5 + (0.0125 * 30000))");
    }

    #[test]
    fn reports_lexical_errors() {
        assert_eq!(
            parse("1 + @"),
            Err(ParseError::UnexpectedChar {
                ch: '@',
                span: Span::new(4, 5),
            })
        );
        assert_eq!(
            parse("1 + ."),
            Err(ParseError::InvalidNumber {
                lexeme: ".".to_string(),
                span: Span::new(4, 5),
            })
        );
        assert_eq!(
            parse("1e+"),
            Err(ParseError::InvalidNumber {
                lexeme: "1e+".to_string(),
                span: Span::new(0, 3),
            })
        );
    }

    #[test]
    fn reports_syntax_errors() {
        assert_eq!(
            parse("(1 + 2"),
            Err(ParseError::UnexpectedToken {
                expected: "`)`",
                found: TokenKind::Eof,
                span: Span::new(6, 6),
            })
        );
        assert_eq!(
            parse("1 + 2 3"),
            Err(ParseError::UnexpectedToken {
                expected: "end of input",
                found: TokenKind::Number(3.0),
                span: Span::new(6, 7),
            })
        );
